import pandas as pd
import numpy as np
from collections import Counter

# Read the data
df = pd.read_excel('/root/data.xlsx', sheet_name='Data', header=7)

# Extract relevant columns
data = df[['Unnamed: 2', 'Unnamed: 3', 'Unnamed: 4', 'Unnamed: 5', 'Unnamed: 6', 'Unnamed: 7', 'Unnamed: 8', 'Unnamed: 9']].copy()
data.columns = ['Turn', 'Game', 'Roll1', 'Roll2', 'Roll3', 'Roll4', 'Roll5', 'Roll6']
data = data.iloc[1:]
data = data.dropna(subset=['Turn', 'Game'])
for col in data.columns:
    data[col] = pd.to_numeric(data[col], errors='coerce')
data = data.dropna()
data = data.astype(int)

print(f"Total turns: {len(data)}")
print(f"Total games: {data['Game'].max()}")

# Scoring functions
def high_and_often(rolls):
    highest = max(rolls)
    count = rolls.count(highest)
    return highest * count

def summation(rolls):
    return sum(rolls)

def highs_and_lows(rolls):
    highest = max(rolls)
    lowest = min(rolls)
    return highest * lowest * (highest - lowest)

def only_two_numbers(rolls):
    unique = set(rolls)
    if len(unique) == 2:
        return 30
    return 0

def all_the_numbers(rolls):
    if set(rolls) == {1, 2, 3, 4, 5, 6}:
        return 40
    return 0

def ordered_subset_of_four(rolls):
    for i in range(3):
        subset = rolls[i:i+4]
        if all(subset[j+1] == subset[j] + 1 for j in range(3)):
            return 50
        if all(subset[j+1] == subset[j] - 1 for j in range(3)):
            return 50
    return 0

def get_all_scores(rolls):
    return {
        'high_and_often': high_and_often(rolls),
        'summation': summation(rolls),
        'highs_and_lows': highs_and_lows(rolls),
        'only_two': only_two_numbers(rolls),
        'all_numbers': all_the_numbers(rolls),
        'ordered_four': ordered_subset_of_four(rolls)
    }

def get_best_game_score(turn1_scores, turn2_scores):
    categories = list(turn1_scores.keys())
    best_score = 0
    for cat1 in categories:
        for cat2 in categories:
            if cat1 != cat2:
                score = turn1_scores[cat1] + turn2_scores[cat2]
                if score > best_score:
                    best_score = score
    return best_score

def get_best_single_turn_score(turn_scores):
    return max(turn_scores.values())

# Group turns by game
game_turns = {}
for _, row in data.iterrows():
    game_num = int(row['Game'])
    rolls = [int(row['Roll1']), int(row['Roll2']), int(row['Roll3']), 
             int(row['Roll4']), int(row['Roll5']), int(row['Roll6'])]
    if game_num not in game_turns:
        game_turns[game_num] = []
    game_turns[game_num].append(get_all_scores(rolls))

# Calculate best score for each game
game_scores = {}
for game_num in range(1, 3001):
    if game_num in game_turns:
        turns = game_turns[game_num]
        if len(turns) == 2:
            game_scores[game_num] = get_best_game_score(turns[0], turns[1])
        elif len(turns) == 1:
            # For incomplete games, use best single category score
            game_scores[game_num] = get_best_single_turn_score(turns[0])
            print(f"Game {game_num} has only 1 turn, score: {game_scores[game_num]}")

print(f"\nGames calculated: {len(game_scores)}")

# Match odd games (Player 1) vs even games (Player 2)
player1_wins = 0
player2_wins = 0
ties = 0

for i in range(1, 1501):
    odd_game = 2 * i - 1
    even_game = 2 * i

    score1 = game_scores.get(odd_game, 0)
    score2 = game_scores.get(even_game, 0)

    if score1 > score2:
        player1_wins += 1
    elif score2 > score1:
        player2_wins += 1
    else:
        ties += 1

print(f"\nPlayer 1 wins: {player1_wins}")
print(f"Player 2 wins: {player2_wins}")
print(f"Ties: {ties}")
print(f"\nAnswer (P1 wins - P2 wins): {player1_wins - player2_wins}")

with open('/root/answer.txt', 'w') as f:
    f.write(str(player1_wins - player2_wins))

print("\nAnswer written to /root/answer.txt")
